//! Cargo-driven `portcls.sys` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is portcls-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "___ImageBase", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "__ImageBase", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "__ImageBase", 0x7ffb00000000u64),
        o => panic!("portcls-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:c:libcntpr", "engine:pseh", "import:ntoskrnl", "import:ks", "import:drmk", "import:hal", "engine:cntpr_rust", "engine:chkstk", "engine:c:memcmp"],
        "x86_64" => &["body", "engine:c:libcntpr", "engine:pseh", "import:ntoskrnl", "import:ks", "import:drmk", "import:hal", "engine:cntpr_rust", "engine:c:memcmp"],
        "aarch64" => &["body", "engine:c:libcntpr", "engine:pseh", "import:ntoskrnl", "import:ks", "import:drmk", "import:hal", "engine:cntpr_rust", "engine:chkstk", "engine:c:memcmp"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/drivers/wdm/audio/backpln/portcls",
        "drivers/wdm/audio/backpln/portcls",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x600"];

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=-sse,-sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("portcls-rust")
        .rust_user_target()
        .c_from_compile_db("portcls_shims", &["drivers/wdm/audio/backpln/portcls/adapter.cpp", "drivers/wdm/audio/backpln/portcls/api.cpp", "drivers/wdm/audio/backpln/portcls/connection.cpp", "drivers/wdm/audio/backpln/portcls/dispatcher.cpp", "drivers/wdm/audio/backpln/portcls/dll.cpp", "drivers/wdm/audio/backpln/portcls/dma_slave.cpp", "drivers/wdm/audio/backpln/portcls/drm.cpp", "drivers/wdm/audio/backpln/portcls/drm_port.cpp", "drivers/wdm/audio/backpln/portcls/filter_topology.cpp", "drivers/wdm/audio/backpln/portcls/filter_dmus.cpp", "drivers/wdm/audio/backpln/portcls/filter_wavecyclic.cpp", "drivers/wdm/audio/backpln/portcls/filter_wavepci.cpp", "drivers/wdm/audio/backpln/portcls/filter_wavert.cpp", "drivers/wdm/audio/backpln/portcls/interrupt.cpp", "drivers/wdm/audio/backpln/portcls/irp.cpp", "drivers/wdm/audio/backpln/portcls/irpstream.cpp", "drivers/wdm/audio/backpln/portcls/miniport.cpp", "drivers/wdm/audio/backpln/portcls/miniport_dmus.cpp", "drivers/wdm/audio/backpln/portcls/miniport_fmsynth.cpp", "drivers/wdm/audio/backpln/portcls/pin_dmus.cpp", "drivers/wdm/audio/backpln/portcls/pin_wavecyclic.cpp", "drivers/wdm/audio/backpln/portcls/pin_wavepci.cpp", "drivers/wdm/audio/backpln/portcls/pin_wavert.cpp", "drivers/wdm/audio/backpln/portcls/pool.cpp", "drivers/wdm/audio/backpln/portcls/port.cpp", "drivers/wdm/audio/backpln/portcls/port_dmus.cpp", "drivers/wdm/audio/backpln/portcls/port_topology.cpp", "drivers/wdm/audio/backpln/portcls/port_wavecyclic.cpp", "drivers/wdm/audio/backpln/portcls/port_wavepci.cpp", "drivers/wdm/audio/backpln/portcls/port_wavert.cpp", "drivers/wdm/audio/backpln/portcls/port_wavertstream.cpp", "drivers/wdm/audio/backpln/portcls/power.cpp", "drivers/wdm/audio/backpln/portcls/propertyhandler.cpp", "drivers/wdm/audio/backpln/portcls/purecall.cpp", "drivers/wdm/audio/backpln/portcls/registry.cpp", "drivers/wdm/audio/backpln/portcls/service_group.cpp", "drivers/wdm/audio/backpln/portcls/undoc.cpp", "drivers/wdm/audio/backpln/portcls/unregister.cpp", "drivers/wdm/audio/backpln/portcls/version.cpp", "drivers/wdm/audio/backpln/portcls/guid.cpp"])
        .rc("drivers/wdm/audio/backpln/portcls/portcls.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("drivers/wdm/audio/backpln/portcls/portcls.spec", "portcls.sys")
        .import_lib("ntoskrnl/ntoskrnl.spec", "ntoskrnl.exe", "ntoskrnl")
        .import_lib("drivers/ksfilter/ks/ks.spec", "ks.sys", "ks")
        .import_lib("drivers/wdm/audio/drm/drmk/drmk.spec", "drmk.sys", "drmk")
        .import_lib("hal/hal.spec", "hal.dll", "hal")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
